/* Public, fictional, browser-local interaction demo. No server/API or authentication. */
(function(root){'use strict';
const HEADERS=['日付','摘要','摘要内容','支払い金額','預かり金額','差引残高','メモ','未資金化区分','入払区分'];
const clone=x=>JSON.parse(JSON.stringify(x));
const now=()=>new Date().toISOString();
const active=p=>p.status==='active'||p.status==='attended';
function seed(){
 const surnames=['鈴木','佐藤','田中','山本','加藤','伊藤','中村','小林','渡辺','山田','高橋','吉田','松井','近藤','石川','林','森','清水','岡田','藤田'];
 const first=['健一','由美','直樹','真理','浩二','恵子','誠','裕子','達也','陽子','修','明美','和也','典子','哲也','久美子','博','美紀','隆','佳代'];
 const people=[];
 for(let cl=1;cl<=10;cl++)for(let j=0;j<10+cl;j++){
  const id=people.length+1;people.push({id,number:'K87-'+String(id).padStart(5,'0'),class:cl,name:surnames[(cl*3+j)%20]+' '+first[(cl+j*3)%20],kana:'サンプル '+String(id).padStart(3,'0'),oldname:j%7===0?'田村':'',display:surnames[(cl*3+j)%20]+' '+first[(cl+j*3)%20],email:'sample'+id+'@example.test',address:'愛知県架空市見本町1-2-3',postal:'000-0000',phone:'000-0000-0000',payer:'サンプル'+String(id).padStart(3,'0'),public:j%8!==0,status:j===9&&cl%3===0?'cancelled':'active',amount:8000,note:'架空データ・実在の卒業生とは関係ありません',created:'2026-10-27T10:00:00.000Z',revision:1});
 }
 const transactions=[],allocations=[];
 people.filter(p=>p.id%3!==0&&active(p)).forEach((p,i)=>{const id=i+1;transactions.push({id,date:'2026-10-27',memo:p.number+' サンプル入金',payer:p.payer,credit:p.id===4?9000:p.id===5?5000:8000,debit:0,balance:100000+i*8000,raw:[],fingerprint:'seed-'+id,state:'confirmed',review:'架空の初期入金',duplicateOf:null,importId:0});allocations.push({id,transactionId:id,personId:p.id,amount:p.id===4?9000:p.id===5?5000:8000,active:true,reason:'架空データの初期割当',at:'2026-10-27T10:00:00.000Z',actor:i%2?'幹事B（サンプル）':'幹事A（サンプル）'});});
 return {schema:1,people,transactions,allocations,imports:[],logs:[{id:1,at:'2026-10-27T10:00:00.000Z',actor:'サンプル初期化',action:'架空データを準備',entity:'demo',before:null,after:{people:people.length},reason:'操作確認用。実際の入金ではありません',result:'成功'}],mail:[],refunds:[],photos:[{id:1,title:'あの頃の校舎を思い描いて',album:'思い出の風景',src:'assets/school-memory.svg',published:true,sample:true},{id:2,title:'また、この街で会おう',album:'思い出の風景',src:'assets/river-memory.svg',published:true,sample:true},{id:3,title:'話の続きは、同じテーブルで',album:'再会のひととき',src:'assets/table-memory.svg',published:true,sample:true}],settings:{dateLabel:'2028年○月○日（未定）',venue:'岡崎ニューグランドホテル',fee:8000,open:'2026-10-01',registration:'2028-07-31',payment:'2028-08-31',change:'2028-09-30',cancel:'2028-09-30',photoEnd:'2029-03-31',capacity:500,clock:'2026-10-27'}};
}
function totalPaid(s,id){return s.allocations.filter(a=>a.personId===id&&a.active).reduce((x,a)=>x+a.amount,0);}
function due(s,p){const billed=p.status==='cancelled'?0:p.amount;return billed-totalPaid(s,p.id)+s.refunds.filter(r=>r.personId===p.id&&r.status==='模擬完了').reduce((x,r)=>x+r.amount,0);}
function paymentLabel(s,p){const n=due(s,p),paid=totalPaid(s,p.id);return n<0?'過払い・返金検討':n===0&&paid?'入金済':n===0?'請求なし':paid?'一部入金':'未入金';}
function counts(s){const list=s.people.filter(active);return {total:list.length,classes:Array.from({length:10},(_,i)=>list.filter(p=>p.class===i+1).length)};}
function audit(s,actor,action,entity,before,after,reason,result='成功'){s.logs.push({id:Math.max(0,...s.logs.map(l=>l.id))+1,at:now(),actor,action,entity:String(entity),before:clone(before===undefined?null:before),after:clone(after===undefined?null:after),reason,result});}
function checkDeadline(s,kind){const date=s.settings.clock;if(date>s.settings[kind])throw new Error('この操作の期限を過ぎています。幹事にお問い合わせください。');if(kind==='registration'&&date<s.settings.open)throw new Error('申込受付開始前です。');}
function validatePerson(s,p,isEdit=false){
 for(const key of ['name','kana','email','address','phone','payer'])if(!String(p[key]||'').trim())throw new Error('必須項目をすべて入力してください。');
 if(!Number.isInteger(Number(p.class))||Number(p.class)<1||Number(p.class)>10)throw new Error('3年1組〜10組を選択してください。');
 if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.email))throw new Error('メールアドレスの形式を確認してください。');
 if(Object.values(p).some(v=>typeof v==='string'&&v.length>1000))throw new Error('入力が長すぎます。');
 if(p.public&&!String(p.display||'').trim())throw new Error('名簿に表示する名前を入力してください。');
 checkDeadline(s,isEdit?'change':'registration');
 if(!isEdit&&counts(s).total>=s.settings.capacity)throw new Error('参加定員に達しています。');
}
function register(s,p){validatePerson(s,p);const id=Math.max(0,...s.people.map(p=>p.id))+1;const n={...clone(p),class:Number(p.class),id,number:'K87-'+String(id).padStart(5,'0'),amount:s.settings.fee,status:'active',created:now(),revision:1};s.people.push(n);audit(s,'申込者（サンプル）','参加申込',n.number,null,{id:n.id,class:n.class,amount:n.amount,public:n.public},'本人の確認操作');s.mail.push({id:s.mail.length+1,personId:id,subject:'参加申込の受付（未送信）',at:now(),body:n.number+' / 仮会費 '+n.amount+'円。これはサンプルです。実際の申込や振込は行わないでください。'});return n;}
function editPerson(s,id,patch){const p=s.people.find(x=>x.id===id);if(!p||!active(p))throw new Error('変更できる申込ではありません。');validatePerson(s,patch,true);const before={class:p.class,name:p.name,public:p.public,revision:p.revision};Object.assign(p,clone(patch),{class:Number(patch.class),revision:p.revision+1});audit(s,'申込者（サンプル）','申込内容の修正',p.number,before,{class:p.class,name:p.name,public:p.public,revision:p.revision},'期限内の本人修正');s.mail.push({id:s.mail.length+1,personId:id,subject:'申込変更（未送信）',at:now(),body:p.number+' 内容を変更しました。'});return p;}
function cancel(s,id,reason){checkDeadline(s,'cancel');const p=s.people.find(x=>x.id===id);if(!p||!active(p))throw new Error('欠席変更できる申込ではありません。');if(!reason.trim())throw new Error('理由を入力してください。');const before=p.status;p.status='cancel_requested';audit(s,'申込者（サンプル）','欠席への変更申請',p.number,{status:before},{status:p.status},reason);return p;}
function parseCSV(text){text=text.replace(/^\uFEFF/,'');const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else if(!quoted&&field.length)throw new Error('CSVの引用符の位置が不正です。');else quoted=!quoted;}else if(c===','&&!quoted){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(x=>x.trim()))rows.push(row);row=[];field='';}else field+=c;}if(quoted)throw new Error('CSVの引用符が閉じられていません。');row.push(field);if(row.some(x=>x.trim()))rows.push(row);return rows;}
function parseMoney(v){const n=String(v||'').normalize('NFKC').replace(/[,￥¥円\s]/g,'');if(!n)return 0;if(!/^\d+$/.test(n))throw new Error('金額の形式が不正です');const x=Number(n);if(!Number.isSafeInteger(x))throw new Error('金額が大きすぎます');return x;}
function parseDate(v){v=String(v).normalize('NFKC').trim();let y,m,d,a;if((a=v.match(/^(\d{4})[\/.-](\d{1,2})[\/.-](\d{1,2})$/))){[,y,m,d]=a;}else if(/^\d{8}$/.test(v)){y=v.slice(0,4);m=v.slice(4,6);d=v.slice(6);}else if(/^\d{6}$/.test(v)){y='20'+v.slice(0,2);m=v.slice(2,4);d=v.slice(4);}else throw new Error('日付の形式が不正です');const date=new Date(Date.UTC(+y,+m-1,+d));if(date.getUTCFullYear()!==+y||date.getUTCMonth()!==+m-1||date.getUTCDate()!==+d)throw new Error('存在しない日付です');return String(y)+'-'+String(+m).padStart(2,'0')+'-'+String(+d).padStart(2,'0');}
function importCSV(s,text,filename,actor){const old=s.imports.find(i=>i.source===text);if(old){audit(s,actor,'同一CSVの再取込を抑止','import:'+old.id,null,{count:0},'同一の内容のファイル');return {id:old.id,repeated:true,count:0,errors:[],duplicates:0};}const rows=parseCSV(text),header=rows.findIndex(r=>JSON.stringify(r.map(x=>x.trim()))===JSON.stringify(HEADERS));if(header<0)throw new Error('指定の9列の見出しが見つかりません。');const id=s.imports.length+1,imp={id,filename,source:text,at:now(),actor,rows:[],count:0,duplicates:0,errors:[],managementRows:header};for(let i=header+1;i<rows.length;i++){const r=rows[i];try{if(r.length!==9)throw new Error('列数が9列ではありません');const date=parseDate(r[0]),debit=parseMoney(r[3]),credit=parseMoney(r[4]),balance=parseMoney(r[5]);if(debit&&credit)throw new Error('入金と出金が同時に指定されています');const fingerprint=JSON.stringify(r),dup=s.transactions.find(t=>t.fingerprint===fingerprint);const review=[];if(dup)review.push('全列一致：重複か別取引か確認');if(debit)review.push('出金：割当不可');if(!debit&&!credit)review.push('金額0：確認');if(r[7]&&!['0','済','資金化済'].includes(r[7].trim()))review.push('未資金化区分を確認');if(credit&&!['入金','入','1'].includes(r[8].trim()))review.push('入払区分を確認');review.push('振込名義列未確定：摘要は参考');const tid=Math.max(0,...s.transactions.map(t=>t.id))+1;s.transactions.push({id:tid,date,memo:r[1]+' / '+r[2]+' / '+r[6],payer:'',credit,debit,balance,raw:r,fingerprint,duplicateOf:dup?dup.id:null,review:review.join('・'),state:'pending',importId:id});imp.rows.push({line:i+1,transactionId:tid,raw:r});imp.count++;if(dup)imp.duplicates++;}catch(e){imp.errors.push({line:i+1,error:e.message,raw:r});}}s.imports.push(imp);audit(s,actor,'銀行CSV取込','import:'+id,null,{filename,count:imp.count,duplicates:imp.duplicates,errors:imp.errors.length},'架空CSVの操作確認');return imp;}
function used(s,tid){return s.allocations.filter(a=>a.transactionId===tid&&a.active).reduce((v,a)=>v+a.amount,0);}
function decide(s,tid,decision,reason,actor){const t=s.transactions.find(x=>x.id===tid);if(!t||t.state!=='pending')throw new Error('確認待ちの明細ではありません。');if(!reason.trim())throw new Error('確認理由を入力してください。');if(!['confirmed','excluded'].includes(decision))throw new Error('判定が不正です。');if(decision==='confirmed'&&(t.debit||!t.credit))throw new Error('出金・0円明細は入金確定できません。');const before=t.state;t.state=decision;audit(s,actor,'銀行明細の判定','transaction:'+tid,{state:before},{state:t.state,credit:t.credit,duplicateOf:t.duplicateOf},reason);}
function allocate(s,tid,pid,amount,reason,actor){const t=s.transactions.find(x=>x.id===tid),p=s.people.find(x=>x.id===pid);if(!t||t.state!=='confirmed'||t.debit)throw new Error('入金明細を先に確認済みにしてください。');if(!p||p.status==='cancelled')throw new Error('有効な申込番号を指定してください。');if(!Number.isSafeInteger(amount)||amount<=0)throw new Error('正の整数金額を入力してください。');if(!reason.trim())throw new Error('確認根拠を入力してください。');const before={paid:totalPaid(s,pid),unallocated:t.credit-used(s,tid),due:due(s,p)};if(amount>before.unallocated)throw new Error('明細の未割当額を超えています。二重割当はできません。');const id=Math.max(0,...s.allocations.map(a=>a.id))+1;s.allocations.push({id,transactionId:tid,personId:pid,amount,active:true,reason,at:now(),actor});audit(s,actor,'入金確定・割当',p.number,before,{allocationId:id,transactionId:tid,amount,paid:totalPaid(s,pid),unallocated:t.credit-used(s,tid),due:due(s,p)},reason);s.mail.push({id:s.mail.length+1,personId:pid,subject:'入金確認（未送信）',at:now(),body:p.number+' / 入金割当 '+amount+'円。差額 '+due(s,p)+'円。実際の入金ではありません。'});return id;}
function unallocate(s,id,reason,actor){const a=s.allocations.find(x=>x.id===id);if(!a||!a.active)throw new Error('取消可能な割当ではありません。');if(!reason.trim())throw new Error('訂正理由が必要です。');const p=s.people.find(p=>p.id===a.personId),before={paid:totalPaid(s,p.id),due:due(s,p),allocationId:id};a.active=false;a.cancelReason=reason;a.cancelledAt=now();audit(s,actor,'入金割当取消',p.number,before,{paid:totalPaid(s,p.id),due:due(s,p),allocationId:id,transactionId:a.transactionId},reason);}
function csvCell(v){v=String(v??'');if(/^[\s]*[=+\-@\t\r]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"';}
function toCSV(rows){return '\uFEFF'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n');}
function fixtures(part=1){const a=['20261027','振込','K87-00003 サンプル003','','8,000','108,000','','0','入金'],b=['261027','振込','K87-00006 サンプル006','','8,000','116,000','','0','入金'],c=['2026/10/27','振込','同日同額同名義の架空例','','8,000','124,000','','0','入金'],d=['2026/10/27','振込','同日同額同名義の架空例','','8,000','132,000','','0','入金'];const rows=part===1?[a,b,c]:part===2?[b,c,d]:[['2026/10/27','振込','該当なし','','6,000','138,000','','未資金化','入金'],['2026/10/27','支払','出金テスト','1,000','','137,000','','','出金'],['20261345','振込','日付エラー','','8,000','145,000','','','入金']];return toCSV([['架空口座・操作確認用・実明細ではありません'],HEADERS,...rows]);}
const API={HEADERS,clone,seed,active,totalPaid,due,paymentLabel,counts,audit,checkDeadline,validatePerson,register,editPerson,cancel,parseCSV,parseMoney,parseDate,importCSV,used,decide,allocate,unallocate,toCSV,fixtures};
if(typeof module!=='undefined'&&module.exports)module.exports=API;root.Reunion=API;
})(typeof globalThis!=='undefined'?globalThis:this);
